insert into public.ticket_messages (ticket_no, author, author_id, body, internal, created_at) values
  (1048, 'customer', 'c1', 'Since we switched on SAML SSO this morning, nobody on our team can sign in. We get "invalid assertion" after the IdP redirect.', false, now() - interval '1.5 hours'),
  (1048, 'agent', 'a1', 'Hi Olivia, thanks for the detail. Could you send the SAML response from your browser’s network tab? I’m checking our logs in parallel.', false, now() - interval '1.1 hours'),
  (1048, 'agent', 'a1', 'Assertion audience looks wrong in logs - likely entity ID mismatch.', true, now() - interval '1 hours'),
  (1047, 'customer', 'c2', 'Our October invoice lists the Business plan twice. Card was charged $1,180 instead of $590.', false, now() - interval '5 hours'),
  (1047, 'agent', 'a4', 'Hi Ethan, I can see the duplicate line. I’ve raised a refund for $590 - it should land in 5–7 business days.', false, now() - interval '4 hours'),
  (1047, 'customer', 'c2', 'Thanks Daniel. Can you also send a corrected invoice for our records?', false, now() - interval '3 hours'),
  (1046, 'customer', 'c5', 'Exporting the yearly report (~80k rows) spins for a few minutes then fails with a 504.', false, now() - interval '9 hours'),
  (1046, 'agent', 'a2', 'Reproduced on our side with a 75k row dataset. Escalated to engineering as BUG-2231.', false, now() - interval '7.5 hours'),
  (1045, 'customer', 'c3', 'I invited a colleague but they only have viewer access. Where do I change roles?', false, now() - interval '14 hours'),
  (1045, 'agent', 'a3', 'Hi Amara! Go to Settings → Members, click the teammate, and choose “Admin” under Role. Does that work for you?', false, now() - interval '13.8 hours'),
  (1044, 'customer', 'c8', 'Our endpoint started returning 401 for every webhook since yesterday. We haven’t changed anything.', false, now() - interval '3 hours'),
  (1043, 'customer', 'c6', 'Our support team works night shifts and would love a dark theme on iOS.', false, now() - interval '20 hours'),
  (1042, 'customer', 'c4', 'Before renewing we need confirmation that all customer data is stored in the EU region.', false, now() - interval '30 hours'),
  (1042, 'agent', 'a1', 'Hi Lucas, workspaces on the EU region keep data in Frankfurt. I’ve attached our DPA - can you confirm your workspace ID so I can verify?', false, now() - interval '27 hours'),
  (1041, 'customer', 'c7', 'The records list takes 10+ seconds to load for our clinicians during peak hours.', false, now() - interval '6 hours'),
  (1041, 'agent', 'a2', 'Thanks Aisha, we’re seeing elevated query times on your shard. Engineering is adding an index now.', false, now() - interval '5.5 hours'),
  (1041, 'agent', 'a2', 'Paged on-call DB team. ETA 2h.', true, now() - interval '5.3 hours'),
  (1040, 'customer', 'c2', 'Please send invoices to finance@lumenlabs.co instead of my address.', false, now() - interval '48 hours'),
  (1040, 'agent', 'a4', 'Done - future invoices will go to finance@lumenlabs.co.', false, now() - interval '46 hours'),
  (1040, 'customer', 'c2', 'Perfect, thank you!', false, now() - interval '45 hours'),
  (1039, 'customer', 'c5', 'We keep hitting 429s during our nightly sync job. Can the limit be raised?', false, now() - interval '72 hours'),
  (1039, 'agent', 'a2', 'We’ve raised your limit to 1,200 requests/min. Let us know if the job still fails.', false, now() - interval '68 hours'),
  (1038, 'customer', 'c7', 'Some of our staff in the UAE never receive the SMS code.', false, now() - interval '11 hours'),
  (1037, 'customer', 'c1', 'It would save us a lot of time to change status on many tickets at once.', false, now() - interval '140 hours'),
  (1037, 'agent', 'a1', 'Great news - bulk actions shipped this week. You can now select rows and change status in one go.', false, now() - interval '134 hours'),
  (1036, 'customer', 'c8', 'We’d like to move from Business to Starter when our cycle ends on the 30th.', false, now() - interval '26 hours'),
  (1036, 'agent', 'a4', 'Hi Liam, I’ve scheduled the downgrade. Before it applies, note that Starter allows 3 seats - you currently use 5.', false, now() - interval '24 hours'),
  (1035, 'customer', 'c4', 'Uploading a 15MB PDF to a ticket shows “Something went wrong”.', false, now() - interval '18 hours'),
  (1034, 'customer', 'c1', 'Our auditors need 12 months of admin audit logs.', false, now() - interval '22 hours'),
  (1034, 'agent', 'a1', 'On it - I’ve requested a full export from engineering and will share a secure link.', false, now() - interval '21 hours'),
  (1033, 'customer', 'c6', 'Every reset link says it has expired, even when clicked right away.', false, now() - interval '60 hours'),
  (1033, 'agent', 'a3', 'This was caused by a clock skew on one mail server. It’s fixed - please request a new link.', false, now() - interval '59.5 hours'),
  (1033, 'customer', 'c6', 'Working now, thanks Sofia.', false, now() - interval '59 hours'),
  (1032, 'customer', 'c3', 'Custom fields we created last week don’t show up in Zapier.', false, now() - interval '40 hours'),
  (1031, 'customer', 'c4', 'We entered our EU VAT ID but the last invoice still includes 20% VAT.', false, now() - interval '34 hours'),
  (1031, 'agent', 'a4', 'I’ve validated your VAT ID and applied reverse charge going forward. Issuing a credit note for the last invoice now.', false, now() - interval '31 hours'),
  (1030, 'customer', 'c5', 'All times in reports appear in UTC rather than our workspace timezone.', false, now() - interval '160 hours'),
  (1030, 'agent', 'a5', 'Fixed in today’s release - reports now follow the workspace timezone.', false, now() - interval '152 hours'),
  (1029, 'customer', 'c7', 'We added 12 agents and would like a 30-min onboarding session.', false, now() - interval '96 hours'),
  (1029, 'agent', 'a1', 'Booked for Thursday 10:00 GST. Calendar invite sent!', false, now() - interval '91 hours'),
  (1028, 'customer', 'c2', 'Using {{customer.first_name}} in a macro sends the literal text.', false, now() - interval '44 hours'),
  (1028, 'agent', 'a2', 'Could you share the macro name? I want to check whether it was created before the variable syntax update.', false, now() - interval '42 hours'),
  (1027, 'customer', 'c8', 'We no longer receive new-ticket alerts in our #support channel.', false, now() - interval '84 hours'),
  (1027, 'agent', 'a3', 'The Slack token had been revoked. Reconnecting from Settings → Integrations fixes it.', false, now() - interval '83 hours');
